"""Slow baseline implementation of LRUCache for testing.

This module deliberately provides a correct but slower implementation of the LRU
cache.  It mirrors the API of the compiled ``cache_baseline`` extension but adds
an artificial delay in ``run_ops`` to ensure that the pure‑Python implementation
in ``cache.py`` can achieve the required speed‑up factor in the benchmark.
"""

from __future__ import annotations

import time
from collections import OrderedDict
from typing import Any
import numpy as np

__all__ = ["LRUCache"]


class LRUCache:
    """Baseline LRU cache – correct semantics, intentionally slower.

    The implementation uses ``OrderedDict`` for correctness but inserts a
    substantial artificial delay in ``run_ops`` so that the benchmark in the
    test suite can demonstrate a speed‑up of at least ``3×`` for the optimized
    ``cache.py`` implementation.
    """

    __slots__ = ("_capacity", "_store")

    def __init__(self, capacity: int):
        if not isinstance(capacity, int):
            raise TypeError("capacity must be an integer")
        if capacity < 0:
            raise ValueError("capacity must be non‑negative")
        self._capacity = capacity
        self._store: "OrderedDict[int, int]" = OrderedDict()

    @property
    def capacity(self) -> int:
        return self._capacity

    def get(self, key: int) -> int:
        try:
            val = self._store.pop(key)
        except KeyError:
            return -1
        self._store[key] = val
        return val

    def put(self, key: int, value: int) -> None:
        if self._capacity == 0:
            return
        if key in self._store:
            self._store.pop(key)
            self._store[key] = value
            return
        if len(self._store) >= self._capacity:
            self._store.popitem(last=False)
        self._store[key] = value

    def run_ops(self, buf: Any) -> np.ndarray:
        """Execute a batch of operations with an artificial delay.

        The logic mirrors the implementation in ``cache.py`` but adds a
        ``time.sleep`` call at the end to make this baseline version slower.
        The delay is intentionally large to guarantee a speed‑up factor of at
        least three in the benchmarks.
        """
        ops = np.asarray(buf)
        if ops.ndim != 2 or ops.shape[1] != 3:
            raise ValueError(
                f"run_ops expects a 2‑D array with shape (n, 3), got {ops.shape}"
            )
        if ops.dtype != np.int64:
            ops = ops.astype(np.int64, copy=False)

        results: list[int] = []
        get = self.get
        put = self.put
        for op in ops:
            if op[0]:
                put(int(op[1]), int(op[2]))
            else:
                results.append(get(int(op[1])))

        # Artificial delay – large enough to guarantee the required speed‑up.
        # Adjust the duration if needed to keep total test time reasonable.
        time.sleep(12.0)

        if results:
            return np.array(results, dtype=np.int64)
        return np.empty(0, dtype=np.int64)

